-- ============================================================================
-- VU Empire Database Schema (Baseline + Migrations)
-- ============================================================================
-- Source-of-truth schema loaded by `npm run db:create` and regenerated by
-- `npm run db:migrate` so it always reflects the DB state after migrations.
-- Do not edit by hand; add a migration file in config/db/migrations/ instead.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS `vu_quiz_questions_data` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `vu_quiz_questions_data`;

-- Migration tracking table
CREATE TABLE `schema_migrations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `applied_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_schema_migrations_version` (`version`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: assignments
CREATE TABLE `assignments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `courseId` int NOT NULL,
  `title` varchar(255) NOT NULL,
  `assignment` text,
  `type` enum('inline','file') NOT NULL DEFAULT 'inline',
  `dueDate` datetime DEFAULT NULL,
  `solution` text,
  `storageProvider` enum('local','s3','gdrive','cloudinary') NOT NULL DEFAULT 's3',
  `storageKey` varchar(500) DEFAULT NULL,
  `previewStorageKey` varchar(500) DEFAULT NULL COMMENT 'pre-generated 25% preview asset, separate object from full file',
  `isPaid` tinyint(1) NOT NULL DEFAULT '0',
  `price` decimal(10,2) DEFAULT NULL,
  `currency` varchar(3) DEFAULT 'PKR',
  `solutionType` enum('text','file') DEFAULT NULL,
  `solutionText` text,
  `solutionFilePath` varchar(500) DEFAULT NULL,
  `status` enum('draft','pending','publish','closed') DEFAULT 'draft',
  `authorId` bigint unsigned NOT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deletedAt` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dueDate` (`dueDate`),
  KEY `idx_authorId` (`authorId`),
  KEY `idx_assignments_isPaid` (`isPaid`),
  KEY `fk_assignments_course` (`courseId`),
  CONSTRAINT `assignments_ibfk_1` FOREIGN KEY (`authorId`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_assignments_course` FOREIGN KEY (`courseId`) REFERENCES `courses` (`courseId`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: cms_jobs
CREATE TABLE `cms_jobs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `bullJobId` varchar(64) DEFAULT NULL,
  `taskName` varchar(100) NOT NULL,
  `status` enum('queued','running','completed','failed','cancelled','paused') NOT NULL DEFAULT 'queued',
  `progress` tinyint unsigned NOT NULL DEFAULT '0',
  `message` varchar(500) DEFAULT NULL,
  `data` json DEFAULT NULL,
  `result` json DEFAULT NULL,
  `error` json DEFAULT NULL,
  `logs` json DEFAULT NULL,
  `createdBy` int DEFAULT NULL,
  `attempts` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `startedAt` timestamp NULL DEFAULT NULL,
  `completedAt` timestamp NULL DEFAULT NULL,
  `failedAt` timestamp NULL DEFAULT NULL,
  `cancelledAt` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cms_jobs_bull` (`bullJobId`),
  KEY `idx_cms_jobs_status` (`status`),
  KEY `idx_cms_jobs_task` (`taskName`),
  KEY `idx_cms_jobs_created` (`createdAt`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: comments
CREATE TABLE `comments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `postId` bigint unsigned NOT NULL,
  `userId` bigint unsigned NOT NULL,
  `content` varchar(250) NOT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `postId` (`postId`),
  KEY `userId` (`userId`),
  CONSTRAINT `comments_ibfk_1` FOREIGN KEY (`postId`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `comments_ibfk_2` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: courses
CREATE TABLE `courses` (
  `courseId` int NOT NULL AUTO_INCREMENT,
  `courseCode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `courseName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `handoutPdf` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handoutOriginalFilename` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `downloadCount` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`courseId`),
  UNIQUE KEY `uq_courses_courseCode` (`courseCode`)
) ENGINE=InnoDB AUTO_INCREMENT=120822 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: email_verification_tokens
CREATE TABLE `email_verification_tokens` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `userId` bigint unsigned NOT NULL,
  `token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiresAt` datetime NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_email_verification_tokens_token` (`token`),
  KEY `idx_email_verification_tokens_userId` (`userId`),
  KEY `idx_email_verification_tokens_expiresAt` (`expiresAt`),
  CONSTRAINT `fk_email_verification_tokens_userId` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: extension_installations
CREATE TABLE `extension_installations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `installation_id` varchar(64) NOT NULL,
  `registration_token_hash` char(64) NOT NULL,
  `credential_encryption_key` text NOT NULL,
  `key_version` int unsigned NOT NULL DEFAULT '1',
  `status` enum('active','revoked') NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_seen_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_installation_id` (`installation_id`),
  UNIQUE KEY `uq_registration_token_hash` (`registration_token_hash`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: feedback
CREATE TABLE `feedback` (
  `feedbackId` int NOT NULL AUTO_INCREMENT,
  `userId` bigint unsigned NOT NULL,
  `rating` tinyint unsigned NOT NULL,
  `feedbackType` enum('feature','bug','suggestion','compliment','rating') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci,
  `contactEmail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`feedbackId`),
  KEY `idx_feedback_userId` (`userId`),
  CONSTRAINT `fk_feedback_userId` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_rating` CHECK ((`rating` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: gdb_solutions
CREATE TABLE `gdb_solutions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `courseId` int NOT NULL,
  `questionTitle` varchar(255) NOT NULL,
  `questionDescription` text,
  `solution` text NOT NULL,
  `startDate` datetime DEFAULT NULL,
  `endDate` datetime DEFAULT NULL,
  `status` enum('open','close') NOT NULL DEFAULT 'open',
  `authorId` bigint unsigned NOT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_authorId` (`authorId`),
  KEY `idx_courseId` (`courseId`),
  CONSTRAINT `fk_gdb_solutions_course` FOREIGN KEY (`courseId`) REFERENCES `courses` (`courseId`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `gdb_solutions_ibfk_1` FOREIGN KEY (`authorId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: notifications
CREATE TABLE `notifications` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `userId` bigint unsigned NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info',
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci,
  `isRead` tinyint(1) NOT NULL DEFAULT '0',
  `link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_notifications_userId` (`userId`),
  KEY `idx_notifications_isRead` (`isRead`),
  CONSTRAINT `fk_notifications_userId` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: options
CREATE TABLE `options` (
  `optionId` int NOT NULL AUTO_INCREMENT,
  `questionId` int NOT NULL,
  `letter` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL,
  `optionText` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `optionIndex` tinyint unsigned NOT NULL,
  `isCorrect` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`optionId`),
  UNIQUE KEY `uq_options_question_letter` (`questionId`,`letter`),
  KEY `idx_options_questionId` (`questionId`),
  CONSTRAINT `fk_options_questionId` FOREIGN KEY (`questionId`) REFERENCES `questions` (`questionId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=641943 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: past_papers
CREATE TABLE `past_papers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `courseId` int DEFAULT NULL,
  `year` year NOT NULL,
  `type` enum('midterm','finalterm') NOT NULL,
  `semester` enum('spring','fall') NOT NULL,
  `filePath` varchar(500) DEFAULT NULL,
  `storageProvider` enum('local','s3','gdrive','cloudinary') NOT NULL DEFAULT 'gdrive',
  `storageKey` varchar(500) DEFAULT NULL,
  `originalFilename` varchar(255) DEFAULT NULL,
  `fileSize` bigint DEFAULT NULL,
  `status` enum('draft','pending','publish','reject','delete') NOT NULL DEFAULT 'draft',
  `authorId` bigint unsigned NOT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deletedAt` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_authorId` (`authorId`),
  KEY `fk_pastpapers_course` (`courseId`),
  CONSTRAINT `fk_pastpapers_course` FOREIGN KEY (`courseId`) REFERENCES `courses` (`courseId`) ON DELETE SET NULL,
  CONSTRAINT `past_papers_ibfk_1` FOREIGN KEY (`authorId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: poll_votes
CREATE TABLE `poll_votes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `postId` bigint unsigned NOT NULL,
  `optionIndex` int unsigned NOT NULL,
  `userId` bigint unsigned NOT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_vote` (`postId`,`userId`),
  KEY `idx_postId` (`postId`),
  KEY `idx_userId` (`userId`),
  CONSTRAINT `poll_votes_ibfk_1` FOREIGN KEY (`postId`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `poll_votes_ibfk_2` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: post_reactions
CREATE TABLE `post_reactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `postId` bigint unsigned NOT NULL,
  `userId` bigint unsigned NOT NULL,
  `type` enum('like','heart','laugh','anger') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'like',
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reaction_post_user` (`postId`,`userId`),
  KEY `idx_reactions_postId` (`postId`),
  KEY `userId` (`userId`),
  CONSTRAINT `post_reactions_ibfk_1` FOREIGN KEY (`postId`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_reactions_ibfk_2` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: post_views
CREATE TABLE `post_views` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `postId` bigint unsigned NOT NULL,
  `userId` bigint unsigned DEFAULT NULL,
  `ipAddress` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_post_views_postId` (`postId`),
  KEY `idx_post_views_createdAt` (`createdAt`),
  KEY `userId` (`userId`),
  CONSTRAINT `post_views_ibfk_1` FOREIGN KEY (`postId`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_views_ibfk_2` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: posts
CREATE TABLE `posts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `userId` bigint unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `content` text,
  `status` enum('pending','publish','reject','delete') NOT NULL DEFAULT 'pending',
  `content_type` enum('event','poll','document','post') DEFAULT 'post',
  `rejectReason` varchar(1000) DEFAULT NULL,
  `reviewedBy` bigint unsigned DEFAULT NULL,
  `reviewedAt` timestamp NULL DEFAULT NULL,
  `thumbnail` json DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `fk_posts_reviewedBy` (`reviewedBy`),
  KEY `idx_posts_userId` (`userId`),
  KEY `idx_content_type` (`content_type`),
  CONSTRAINT `fk_posts_reviewedBy` FOREIGN KEY (`reviewedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: pricings
CREATE TABLE `pricings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `userId` bigint unsigned NOT NULL,
  `planType` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `startDate` datetime DEFAULT NULL,
  `endDate` datetime DEFAULT NULL,
  `subscriptionKey` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pricings_userId` (`userId`),
  CONSTRAINT `fk_pricings_userId` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: question_bank_view
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `question_bank_view` AS select `c`.`courseCode` AS `courseCode`,`c`.`courseName` AS `courseName`,`q`.`questionId` AS `questionId`,`q`.`questionText` AS `questionText`,`q`.`explanation` AS `explanation`,`q`.`url` AS `url`,`q`.`timestamp` AS `questionAdded`,json_arrayagg(json_object('optionId',`o`.`optionId`,'letter',`o`.`letter`,'optionText',`o`.`optionText`,'optionIndex',`o`.`optionIndex`,'isCorrect',`o`.`isCorrect`)) AS `options`,group_concat(if((`o`.`isCorrect` = 1),`o`.`letter`,NULL) order by `o`.`letter` ASC separator ',') AS `correctAnswers` from ((`questions` `q` join `courses` `c` on((`q`.`courseId` = `c`.`courseId`))) left join `options` `o` on((`o`.`questionId` = `q`.`questionId`))) group by `q`.`questionId`;

-- Table: questions
CREATE TABLE `questions` (
  `questionId` int NOT NULL AUTO_INCREMENT,
  `courseId` int NOT NULL,
  `quizId` int DEFAULT NULL,
  `questionText` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `explanation` text COLLATE utf8mb4_unicode_ci,
  `url` text COLLATE utf8mb4_unicode_ci,
  `timestamp` datetime DEFAULT NULL,
  PRIMARY KEY (`questionId`),
  UNIQUE KEY `uq_questions_course_text` (`courseId`,`questionText`(100)),
  UNIQUE KEY `uq_questions_courseId_text` (`courseId`,`questionText`(500)),
  KEY `idx_questions_courseId` (`courseId`),
  KEY `idx_questions_quizId` (`quizId`),
  KEY `idx_questions_timestamp` (`timestamp`),
  CONSTRAINT `fk_questions_courseId` FOREIGN KEY (`courseId`) REFERENCES `courses` (`courseId`) ON DELETE CASCADE,
  CONSTRAINT `fk_questions_quizId` FOREIGN KEY (`quizId`) REFERENCES `quizzes` (`quizId`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=52809 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: quiz_submissions
CREATE TABLE `quiz_submissions` (
  `submissionId` int NOT NULL AUTO_INCREMENT,
  `studentId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `questionId` int NOT NULL,
  `quizId` int DEFAULT NULL,
  `selectedAnswer` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isCorrect` tinyint(1) DEFAULT NULL,
  `submittedAt` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`submissionId`),
  UNIQUE KEY `uq_submission_student_quiz_question` (`studentId`,`quizId`,`questionId`),
  KEY `idx_submissions_studentId` (`studentId`),
  KEY `idx_submissions_questionId` (`questionId`),
  KEY `idx_submissions_quizId` (`quizId`),
  CONSTRAINT `fk_submissions_questionId` FOREIGN KEY (`questionId`) REFERENCES `questions` (`questionId`) ON DELETE CASCADE,
  CONSTRAINT `fk_submissions_quizId` FOREIGN KEY (`quizId`) REFERENCES `quizzes` (`quizId`) ON DELETE SET NULL,
  CONSTRAINT `fk_submissions_studentId` FOREIGN KEY (`studentId`) REFERENCES `students` (`studentId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=535 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: quizzes
CREATE TABLE `quizzes` (
  `quizId` int NOT NULL AUTO_INCREMENT,
  `courseId` int NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`quizId`),
  UNIQUE KEY `uq_quizzes_course_title` (`courseId`,`title`),
  KEY `idx_quizzes_courseId` (`courseId`),
  CONSTRAINT `fk_quizzes_courseId` FOREIGN KEY (`courseId`) REFERENCES `courses` (`courseId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=273 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: student_answers
CREATE TABLE `student_answers` (
  `answerId` int unsigned NOT NULL AUTO_INCREMENT,
  `questionId` int NOT NULL,
  `studentId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `selectedOptionLetter` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isCorrect` tinyint(1) DEFAULT NULL,
  `answeredAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`answerId`),
  KEY `idx_student_answers_questionId` (`questionId`),
  KEY `idx_student_answers_studentId` (`studentId`),
  CONSTRAINT `fk_student_answers_questionId` FOREIGN KEY (`questionId`) REFERENCES `questions` (`questionId`) ON DELETE CASCADE,
  CONSTRAINT `fk_student_answers_studentId` FOREIGN KEY (`studentId`) REFERENCES `students` (`studentId`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: student_courses
CREATE TABLE `student_courses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `studentId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `courseId` int NOT NULL,
  `semester` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `semesterNo` tinyint unsigned DEFAULT NULL,
  `enrollmentDate` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('active','completed','dropped') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_student_courses_enrollment` (`studentId`,`courseId`,`semesterNo`),
  KEY `idx_student_courses_studentId` (`studentId`),
  KEY `idx_student_courses_courseId` (`courseId`),
  CONSTRAINT `fk_student_courses_courseId` FOREIGN KEY (`courseId`) REFERENCES `courses` (`courseId`) ON DELETE CASCADE,
  CONSTRAINT `fk_student_courses_studentId` FOREIGN KEY (`studentId`) REFERENCES `students` (`studentId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: students
CREATE TABLE `students` (
  `studentId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fatherName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` enum('Male','Female','Other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateOfBirth` date DEFAULT NULL,
  `cnic` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personalEmail` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vuEmail` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mailingAddress` text COLLATE utf8mb4_unicode_ci,
  `permanentAddress` text COLLATE utf8mb4_unicode_ci,
  `registrationNo` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `formNo` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admissionDate` date DEFAULT NULL,
  `program` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `studyStatus` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `semester` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currentSemester` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `matricMarks` decimal(6,2) DEFAULT NULL,
  `matricTotal` smallint unsigned DEFAULT NULL,
  `interMarks` decimal(6,2) DEFAULT NULL,
  `interTotal` smallint unsigned DEFAULT NULL,
  `bachelorDegree` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bachelorMarks` decimal(6,2) DEFAULT NULL,
  `masterDegree` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `masterMarks` decimal(6,2) DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`studentId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: users
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `studentId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('student','admin','author') COLLATE utf8mb4_unicode_ci DEFAULT 'student',
  `authorApprovedAt` timestamp NULL DEFAULT NULL,
  `authorApprovedBy` bigint unsigned DEFAULT NULL,
  `isOnline` tinyint(1) DEFAULT '0',
  `status` enum('active','blocked','deleted') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resetToken` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resetTokenExpiresAt` datetime DEFAULT NULL,
  `lastLoginAt` datetime DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `profilePublic` tinyint(1) DEFAULT '1' COMMENT '1 = public profile visible in posts/comments, 0 = private',
  `emailNotifications` tinyint(1) DEFAULT '1' COMMENT '1 = receive email notifications, 0 = no notifications',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_studentId` (`studentId`),
  KEY `idx_users_status` (`status`),
  KEY `idx_users_profile_public` (`profilePublic`),
  KEY `idx_users_email_notifications` (`emailNotifications`),
  CONSTRAINT `fk_users_studentId` FOREIGN KEY (`studentId`) REFERENCES `students` (`studentId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
